"""Feasibility and gauge-range computation for a single installation setup."""

from itertools import product


def _eval(coefficients, offset, x):
    """Evaluate offset + sum(coefficients[d] * x[d]) for a displacement vector."""
    total = offset
    for datum, coeff in coefficients.items():
        total += coeff * x[datum]
    return total


def _satisfies(constraint, x):
    value = _eval(constraint.get("coefficients", {}), 0, x)
    return constraint["min"] <= value <= constraint["max"]


def setup_ranges(request, setup, chosen):
    """Return per-gauge [min, max] over feasible integer vectors, or None.

    A vector is feasible when it lies inside every inclusive bound, satisfies
    the common physical constraints, the setup constraints, and every
    installation reading under the fixed board selection.
    """
    bounds = request["bounds"]
    datums = list(bounds.keys())
    intervals = [range(bounds[d][0], bounds[d][1] + 1) for d in datums]

    physical_constraints = request.get("physical_constraints", [])
    setup_constraints = setup.get("constraints", [])
    readings = setup.get("readings", [])
    gauges = request.get("gauges", [])

    # Precompute per-reading channel evaluators for the chosen settings.
    reading_specs = []
    for reading in readings:
        setting = chosen[reading["board"]]
        channel = setting["channels"][reading["channel"]]
        reading_specs.append(
            (channel.get("coefficients", {}), channel.get("offset", 0),
             reading["raw"])
        )

    gauge_specs = [
        (gauge["id"], gauge.get("base", 0), gauge.get("coefficients", {}))
        for gauge in gauges
    ]

    minima = {gid: None for gid, _, _ in gauge_specs}
    maxima = {gid: None for gid, _, _ in gauge_specs}

    found = False
    for combo in product(*intervals):
        x = dict(zip(datums, combo))

        if not all(_satisfies(c, x) for c in physical_constraints):
            continue
        if not all(_satisfies(c, x) for c in setup_constraints):
            continue

        ok = True
        for coeffs, offset, raw in reading_specs:
            value = _eval(coeffs, offset, x)
            if not (raw[0] <= value <= raw[1]):
                ok = False
                break
        if not ok:
            continue

        found = True
        for gid, base, coeffs in gauge_specs:
            value = base + _eval(coeffs, 0, x)
            if minima[gid] is None or value < minima[gid]:
                minima[gid] = value
            if maxima[gid] is None or value > maxima[gid]:
                maxima[gid] = value

    if not found:
        return None

    return {gid: [minima[gid], maxima[gid]] for gid, _, _ in gauge_specs}

