from packages.analysis.setup_lattice import setup_ranges

def make_request(bounds, physical, setup, gauges):
    return {"bounds": bounds, "physical_constraints": physical, "setups": [setup], "gauges": gauges}

class TestSetupRanges(unittest.TestCase):
    def test_local_check_ranges(self):
        request = make_request(
            {"x": [0, 2], "y": [0, 2]},
            [{"coefficients": {"x": 1, "y": 1}, "min": 1, "max": 2}],
            {"id": "s", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [2, 2]}]},
            [{"id": "sum", "base": 0, "coefficients": {"x": 1, "y": 1}},
             {"id": "diff", "base": 0, "coefficients": {"x": 1, "y": -1}}],
        )
        chosen = {"A": {"id": "a", "penalty": 0, "channels": {"c": {"coefficients": {"x": 2}, "offset": 0}}}}
        result = setup_ranges(request, request["setups"][0], chosen)
        self.assertEqual(result, {"sum": [1, 2], "diff": [0, 1]})

    def test_local_check_infeasible(self):
        request = make_request(
            {"x": [0, 2], "y": [0, 2]},
            [{"coefficients": {"x": 1, "y": 1}, "min": 1, "max": 2}],
            {"id": "s", "constraints": [], "readings": [{"board": "A", "channel": "c", "raw": [1, 1]}]},
            [{"id": "sum", "base": 0, "coefficients": {"x": 1, "y": 1}}],
        )
        chosen = {"A": {"id": "a", "penalty": 0, "channels": {"c": {"coefficients": {"x": 2}, "offset": 0}}}}
        result = setup_ranges(request, request["setups"][0], chosen)
        self.assertIsNone(result)

if __name__ == "__main__":
    unittest.main()
