from runtime import build, read

def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    raise NotImplementedError

def load_payload(path):
    return read(path)

def build_component(root, contract):
    return build(root, contract, transform)

def compatible_settings(request):
    'Accept the public request and return a mapping from every board ID to a list of its original setting dicts that satisfy every applicable calibration. Calibration readings use the given complete displacement vectors, channel offsets, integer coefficients, and inclusive raw intervals. Preserve feasible settings with equal coefficients or equal penalties. Installation constraints do not restrict calibration pieces.\n\nLocal check: Give board A three settings whose single channel reads x plus offsets 1, 0, and 2. For a calibration with x=2 and raw range [3, 4], only the first and third setting IDs qualify. Add a physical constraint requiring installation x=1 and confirm it does not affect this result.'
    raise NotImplementedError

def setup_ranges(request, setup, chosen):
    'Accept the public request, one original setup dict, and chosen as a mapping from board ID to the original selected setting dict. Return None if no integer displacement vector satisfies the inclusive global bounds, the common physical constraints, the setup constraints, and the installation readings. Otherwise return a mapping of every gauge ID to a two-integer list [minimum, maximum] across all feasible vectors for this setup and fixed board selection.\n\nLocal check: Give x and y bounds [0, 2], require 1 <= x+y <= 2, and use a setting whose channel reads 2*x. A setup requiring raw [2, 2] has ranges sum [1, 2] and difference x-y [0, 1]. The same setup with raw [1, 1] has no integer solution and returns None.'
    raise NotImplementedError

