from itertools import product


def _eval(coefficients, offset, x):
    """Evaluate offset + sum(coefficients[d] * x[d]) for a displacement vector."""
    total = offset
    for datum, coeff in coefficients.items():
        total += coeff * x[datum]
    return total


def _satisfies(constraint, x):
    value = _eval(constraint.get("coefficients", {}), 0, x)
    return constraint["min"] <= value <= constraint["max"]


def setup_ranges(request, setup, chosen):
